-- # Lernfeld 5: Cyberphysische Systeme > ## Testgetriebene Entwicklung > - Tests > - Maßnahmen > - Code Coverage Analyse

INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann die Code Coverage Analyse in der testgetriebenen Entwicklung (TDD) zeigen, welche Teile des Codes ungetestet sind?', 2, '[{"text": "Ja", "correct": true, "because": "Zeigt abgedeckte und nicht abgedeckte Bereiche"}, {"text": "Nein", "correct": false, "because": "Hauptzweck der Analyse"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist eine 100%ige Code Coverage in TDD zwingend erforderlich, um die Qualität zu sichern?', 2, '[{"text": "Nein", "correct": true, "because": "Qualität hängt von Testgüte ab, nicht nur Abdeckung"}, {"text": "Ja", "correct": false, "because": "100% nicht immer nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Können hohe Code Coverage Werte in TDD irreführend sein, wenn die Tests schlecht designed sind?', 2, '[{"text": "Ja", "correct": true, "because": "Abdeckung ohne Qualität ist wenig aussagekräftig"}, {"text": "Nein", "correct": false, "because": "Testdesign beeinflusst Aussagekraft"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Code Coverage Analyse in TDD manuell durchgeführt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Tools automatisieren die Analyse"}, {"text": "Ja", "correct": false, "because": "Automatisierung ist Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Code Coverage Analyse in TDD die Fehlerfreiheit der Software garantieren?', 2, '[{"text": "Nein", "correct": true, "because": "Abdeckung zeigt nur getestete Bereiche, nicht Fehlerfreiheit"}, {"text": "Ja", "correct": false, "because": "Keine absolute Garantie"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt die Code Coverage Analyse in TDD?', 2, '[{"text": "Erkennung ungetesteter Code-Bereiche", "correct": true, "because": "Hauptzweck der Analyse"}, {"text": "Optimierung der Laufzeit", "correct": false, "because": "Nicht primäres Ziel"}, {"text": "Erstellung eines Fehlerberichts", "correct": false, "because": "Nebenprodukt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Metrik wird in der Code Coverage Analyse häufig verwendet, um die Testabdeckung zu bewerten?', 3, '[{"text": "Statement Coverage", "correct": true, "because": "Misst abgedeckte Anweisungen"}, {"text": "Zeilenanzahl des Codes", "correct": false, "because": "Keine Coverage-Metrik"}, {"text": "Anzahl der Entwickler", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool unterstützt typischerweise die Code Coverage Analyse in TDD?', 2, '[{"text": "Coverage-Tool (z.B. JaCoCo)", "correct": true, "because": "Automatisiert Abdeckungsmessung"}, {"text": "Texteditor", "correct": false, "because": "Kein Analysetool"}, {"text": "Debugger", "correct": false, "because": "Fehleranalyse, nicht Coverage"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt der Code Coverage Analyse ist in TDD entscheidend, um die Testqualität zu verbessern?', 2, '[{"text": "Identifikation von Lücken", "correct": true, "because": "Zeigt ungetestete Bereiche"}, {"text": "Verkürzung der Testzeit", "correct": false, "because": "Nicht primär"}, {"text": "Erhöhung der Code-Komplexität", "correct": false, "because": "Kein Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aussage trifft auf die Code Coverage Analyse in TDD am besten zu?', 2, '[{"text": "Sie ist ein Indikator für Testabdeckung", "correct": true, "because": "Misst getesteten Code"}, {"text": "Sie ersetzt die Fehlerbehebung", "correct": false, "because": "Nur Messung"}, {"text": "Sie garantiert fehlerfreien Code", "correct": false, "because": "Keine Garantie"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Code Coverage Metriken werden in TDD häufig analysiert?', 4, '[{"text": "Statement Coverage", "correct": true, "because": "Misst Anweisungen"}, {"text": "Branch Coverage", "correct": true, "because": "Misst Verzweigungen"}, {"text": "Function Coverage", "correct": true, "because": "Misst Funktionsaufrufe"}, {"text": "Line Count", "correct": false, "because": "Keine Coverage-Metrik"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Code Coverage Analyse in TDD?', 3, '[{"text": "Erkennung ungetesteter Bereiche", "correct": true, "because": "Zeigt Lücken"}, {"text": "Verbesserung der Testqualität", "correct": true, "because": "Fördert vollständige Tests"}, {"text": "Automatische Fehlerbehebung", "correct": false, "because": "Nur Messung"}, {"text": "Richtung für Testentwicklung", "correct": true, "because": "Zeigt, wo Tests fehlen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen gibt es bei der Code Coverage Analyse in TDD?', 3, '[{"text": "Irreführende hohe Werte", "correct": true, "because": "Ohne Qualität wenig aussagekräftig"}, {"text": "Hoher Zeitaufwand", "correct": true, "because": "Analyse und Verbesserung nötig"}, {"text": "Keine Tool-Unterstützung", "correct": false, "because": "Tools verfügbar"}, {"text": "Komplexität bei großen Projekten", "correct": true, "because": "Viele Bereiche zu prüfen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Aussagekraft der Code Coverage Analyse in TDD?', 4, '[{"text": "Qualität der Testfälle", "correct": true, "because": "Bestimmt Relevanz"}, {"text": "Abdeckungsmetrik", "correct": true, "because": "Art der Messung"}, {"text": "Teamgröße", "correct": false, "because": "Irrelevant"}, {"text": "Testdesign", "correct": true, "because": "Effektivität der Tests"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen können nach einer Code Coverage Analyse in TDD ergriffen werden?', 3, '[{"text": "Ergänzung fehlender Testfälle", "correct": true, "because": "Lücken schließen"}, {"text": "Refactoring ungetesteten Codes", "correct": true, "because": "Struktur verbessern"}, {"text": "Verkürzung des Codes", "correct": false, "because": "Nicht primär"}, {"text": "Erhöhung der Testabdeckung", "correct": true, "because": "Qualität steigern"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Code Coverage Analyse in TDD zeigt ungetestete Bereiche an. b) 100% Code Coverage bedeutet fehlerfreien Code.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Lücken sichtbar, Fehlerfreiheit nicht garantiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Code Coverage Analyse ist in TDD optional. b) Hohe Abdeckung kann ohne gute Tests irreführend sein.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Analyse wichtig, Qualität entscheidend"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Code Coverage Tools automatisieren die Analyse in TDD. b) Branch Coverage ist irrelevant für TDD.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Tools Standard, Branch Coverage nützlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Code Coverage Analyse hilft, Testlücken zu schließen. b) TDD erfordert keine Code Coverage Analyse.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Lücken sichtbar, Analyse unterstützend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Code Coverage Analyse kann die Testqualität verbessern. b) Eine hohe Abdeckung ersetzt die Fehlerbehebung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Qualität steigt, Behebung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

